let cart=[], currentItem=null, currentAddonsObj={}; function openZoom(src) { document.getElementById('imgZoomTarget').src = src; document.getElementById('zoomModal').style.display = "block"; } function closeZoom() { document.getElementById('zoomModal').style.display = "none"; }
function openItemModal(i, categories){  currentItem=i; currentAddonsObj=categories; document.getElementById('modalItemName').innerText=i.name; document.getElementById('modalItemDesc').innerText=i.description||''; document.getElementById('modalItemTotal').innerText=(parseFloat(i.promotional_price)>0?parseFloat(i.promotional_price):parseFloat(i.price)).toFixed(2); document.getElementById('itemObs').value = ''; let html = ''; Object.values(categories).forEach(cat => { let freeTxt = cat.free_limit > 0 ? `(Escolha ${cat.free_limit} Grátis)` : ''; if(parseInt(cat.max_limit) > 0) freeTxt += ` (Máx: ${cat.max_limit})`; html += `<h6 class="fw-bold mt-3 border-bottom pb-1">${cat.name} <small class="text-success">${freeTxt}</small></h6>`; cat.items.forEach(item => { let p = parseFloat(item.price); let pLabel = (cat.free_limit > 0) ? "" : (p>0 ? `+ R$ ${p.toFixed(2)}` : "Grátis"); html += `<div class="form-check py-1"><input class="form-check-input addon-check" type="checkbox" value="${item.id}" data-cat="${cat.id}" data-price="${p}" id="ad_${item.id}" onchange="calcItemTotal(this)"><label class="form-check-label d-flex justify-content-between w-100" for="ad_${item.id}" style="cursor:pointer"><span>${item.name}</span> <span id="lbl_${item.id}" class="text-muted small fw-bold">${pLabel}</span></label></div>`; }); }); document.getElementById('addonsList').innerHTML = html; new bootstrap.Modal(document.getElementById('itemModal')).show(); }
function calcItemTotal(elem){ let total = parseFloat(currentItem.promotional_price)>0?parseFloat(currentItem.promotional_price):parseFloat(currentItem.price); Object.values(currentAddonsObj).forEach(cat => { let checked = document.querySelectorAll(`.addon-check[data-cat="${cat.id}"]:checked`); let checkedCount = checked.length; if(parseInt(cat.max_limit) > 0 && checkedCount > parseInt(cat.max_limit)) { if(elem && elem.dataset.cat == cat.id && elem.checked) { alert(`Você só pode escolher no máximo ${cat.max_limit} opções.`); elem.checked = false; checkedCount--; } } if(parseInt(cat.allow_extra) == 0 && checkedCount > parseInt(cat.free_limit) && parseInt(cat.free_limit) > 0) { if(elem && elem.dataset.cat == cat.id && elem.checked) { alert(`Você só pode escolher ${cat.free_limit} opções.`); elem.checked = false; } } let updatedChecked = document.querySelectorAll(`.addon-check[data-cat="${cat.id}"]:checked`); updatedChecked.forEach((el, index) => { let lbl = document.getElementById(`lbl_${el.value}`); let originalPrice = parseFloat(el.getAttribute('data-price')); if (index < parseInt(cat.free_limit)) { lbl.innerHTML = "<span class='text-success fw-bold'>Grátis (Incluso)</span>"; } else { total += originalPrice; lbl.innerHTML = "+ R$ " + originalPrice.toFixed(2); } }); document.querySelectorAll(`.addon-check[data-cat="${cat.id}"]:not(:checked)`).forEach(el => { let p = parseFloat(el.getAttribute('data-price')); let lbl = document.getElementById(`lbl_${el.value}`); if (parseInt(cat.free_limit) > 0) { lbl.innerText = (updatedChecked.length < parseInt(cat.free_limit)) ? "" : (p > 0 ? `+ R$ ${p.toFixed(2)}` : "Grátis"); } else { lbl.innerText = p > 0 ? `+ R$ ${p.toFixed(2)}` : "Grátis"; } }); }); document.getElementById('modalItemTotal').innerText=total.toFixed(2); }
